// Local interaction layer; the original article and evidence data remain unchanged.
const team={checker:{name:'Quellenprüfer',scope:'Sources and claims',icon:'▱',visible:false,enabled:true,mode:'Suggest'},historian:{name:'Historiker',scope:'Historical context',icon:'◷',visible:false,enabled:true,mode:'Suggest'},lektor:{name:'Lektor',scope:'Writing support',icon:'⋯',visible:false,enabled:true,mode:'Suggest'}};
const focuses={Clarity:true,Structure:true,Grammar:true,Tone:true,Shortening:true,Repetition:true};
let panelView='writing';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const prefs=JSON.parse(read('authoria-team')||'null');if(prefs){for(const k of Object.keys(team)){if(prefs.team?.[k]){team[k].enabled=prefs.team[k].enabled!==false;team[k].mode=['Silent','Suggest','Proactive'].includes(prefs.team[k].mode)?prefs.team[k].mode:'Suggest';}}for(const f of Object.keys(focuses))if(typeof prefs.focuses?.[f]==='boolean')focuses[f]=prefs.focuses[f];}}catch{}
function persistTeam(){save('authoria-team',JSON.stringify({team,focuses}))}
function focusControls(){return `<fieldset class="focus-controls"><legend>Lektor focus areas</legend>${Object.entries(focuses).map(([f,on])=>`<label><input type="checkbox" data-focus="${f}" ${on?'checked':''}>${f}</label>`).join('')}</fieldset>`}
function teamCard(k,settings=false){const r=team[k];return `<section class="team-card ${k}"><div class="team-heading"><span class="role-symbol">${r.icon}</span><div><strong>${r.name}</strong><small>${r.scope}</small></div></div>${settings?`<label class="setting-line"><span>Enabled in AI Team</span><input type="checkbox" data-enabled="${k}" ${r.enabled?'checked':''}></label><label class="setting-line"><span>Intervention mode</span><select data-mode="${k}" aria-label="${r.name} intervention mode" ${!r.enabled?'disabled':''}>${['Silent','Suggest','Proactive'].map(m=>`<option ${r.mode===m?'selected':''}>${m}</option>`).join('')}</select></label>`:''}<label class="setting-line visibility-line"><span>Show annotations</span><input type="checkbox" role="switch" aria-label="Show ${r.name} annotations" data-visible="${k}" ${r.visible?'checked':''} ${!r.enabled?'disabled':''}></label>${!r.enabled?'<small class="disabled-note">Not enabled · configure in AI Team settings</small>':''}${k==='lektor'&&r.visible&&r.enabled?focusControls()+'<button class="text-button review-lektor" data-review-lektor>Review observations ↗</button>':''}</section>`}
function teamHome(){return `<div class="label">AI Team <button class="text-button" data-settings>Settings ↗</button></div><p class="resource-intro">Your team is available. Choose which annotations to see while you write.</p>${Object.keys(team).map(k=>teamCard(k)).join('')}<p class="quiet-note">Visibility is separate from team membership. All annotations start hidden; your text stays yours.</p><button class="empty-example" id="example"><small>EXPLORE CONNECTED EVIDENCE</small>“Cycling in the city increased by 24%…”<span>View sources ↗</span></button>${automaticObservations()}`}
function settingsPanel(){panelView='settings';$('#panel').innerHTML=`<button class="back" data-writing>← Back to writing</button><div class="label">AI Team settings</div><p class="resource-intro">Configure each role independently. No mode edits the article.</p><details class="mode-help"><summary>About intervention modes</summary><p><b>Silent:</b> responds only when explicitly requested.</p><p><b>Suggest:</b> offers a subtle indication of available assistance.</p><p><b>Proactive:</b> automatically surfaces relevant observations.</p><p>Annotation visibility remains your choice in every mode.</p></details>${Object.keys(team).map(k=>teamCard(k,true)).join('')}`;selectNav('AI Team');openMobile()}
function why(text){return `<details class="why"><summary>Why am I seeing this?</summary><p>${text}</p></details>`}
function observation(k,title,body,reason,expanded=false){const r=team[k];return `<div class="suggestion ${k}"><button data-role="${k}" aria-expanded="${expanded}"><span class="role-symbol">${r.icon}</span><span><strong>${r.name}</strong><small>${title}</small></span><span class="arrow">${expanded?'−':'+'}</span></button><div class="detail" ${expanded?'':'hidden'}>${body}${why(reason)}</div></div>`}
const lektorObservations={Clarity:['Several moving subjects share one sentence.','Consider whether the relationship between commuters, delivery vans and café customers is clear.'],Structure:['The opening moves from a street scene to a citywide trend.','Consider whether a short transition would help connect the scene with the figures.'],Grammar:['The opening uses present tense; the measured change uses past tense.','Consider whether this distinction consistently separates the scene from the reporting period.'],Tone:['“Weave past” creates a vivid impression of movement.','Consider whether that tone matches your reporting and intended audience.'],Shortening:['The opening paragraph contains two sentences and several descriptive details.','Consider which details are essential to introduce the story.'],Repetition:['“Commuters” and “commute” recur across the draft.','Consider whether the repetition supports the theme or could be reduced.']};
function lektorCards(expanded=false){return Object.entries(focuses).filter(([,on])=>on).map(([f])=>observation('lektor',f+' · '+lektorObservations[f][0],`<p>${lektorObservations[f][1]}</p><p>You decide whether to revise. No changes have been made.</p>`,`You enabled ${f.toLowerCase()} as a Lektor focus. This is a mocked observation tied to the opening paragraph, not an assessment of writing quality.`,expanded)).join('')||'<p class="quiet-note">No focus areas selected. Enable a focus area to see Lektor observations.</p>'}
roles=function(expanded=false){
const quantitative=activeClaim==='cycling';
let html='<div class="section-title">AI perspectives <small>Optional · you decide</small></div>';
if(team.checker.enabled)html+=observation('checker',quantitative?'Sources contain different figures.':'Sources use different milestones.',quantitative?'<p>The figures describe different samples and methods. The sources alone do not establish one definitive citywide increase.</p><p>Consider checking definitions with each source before deciding how to describe the change.</p>':'<p>The dates describe pilots, programme approval and completion. Consider specifying which milestone the article refers to.</p>',quantitative?'This sentence contains a quantitative claim and three connected sources report different values.':'This sentence refers to a start date, and the connected sources describe different milestones.',expanded);
if(team.historian.enabled)html+=observation('historian','Historical context available.','<ol class="context-timeline"><li><b>2017</b><span>Pilot routes opened</span></li><li><b>2018</b><span>Expansion programme approved</span></li><li><b>2019</b><span>First connected corridor completed</span></li></ol><p>Mock archive: City Transport Office, network timeline.</p><p>Chronology provides context but does not prove causality. These dates alone do not explain the change in cycling.</p>','The mocked archive contains milestones relevant to the cycling network mentioned in this article. Historical context is available for you to consider.',expanded);
html+=`<div class="context-role-available lektor"><span class="role-symbol">${team.lektor.icon}</span><div><strong>Lektor</strong><small>${team.lektor.enabled?'Available · no observation for this claim':'Not enabled in AI Team'}</small></div><button class="text-button" data-settings>Settings ↗</button></div>`;
return html;
};
function automaticObservations(){return Object.entries(team).filter(([,r])=>r.enabled&&r.visible&&r.mode==='Proactive').map(([k])=>k==='lektor'?lektorCards(true):observation(k,k==='checker'?'Connected sources report different figures':'Historical context available',k==='checker'?'<p>The cycling sources report 24%, 18% and 31%, using different samples. Consider comparing their methods.</p>':'<p>The mocked archive distinguishes 2017 pilots, 2018 approval and 2019 completion. This chronology does not establish causation.</p>',`You chose Proactive mode and enabled ${team[k].name} annotations. This observation is based on the existing mock article and sources.`,true)).join('')}
function annotate(){for(const k of Object.keys(team))$('#article').classList.toggle('show-'+k,team[k].enabled&&team[k].visible);const ps=$('#article').querySelectorAll('p');ps.forEach((p,i)=>{p.dataset.section=String(i);p.classList.toggle('lektor-anchor',i===0&&Object.values(focuses).some(Boolean));});const c=$('[data-claim="cycling"]');if(c)c.title=team.checker.visible?'▱ Sources connected · sources contain different figures':'';const h=$('[data-claim="history"]');if(h)h.title=team.historian.visible?'◷ Historical context available':team.checker.visible?'▱ Sources connected · different milestones':'';persistTeam()}
const oldRender=render;
render=function(next='default',claim=activeClaim){panelView='writing';document.querySelectorAll('[data-evidence]').forEach(n=>n.classList.remove('selected'));oldRender(next,claim);if(next==='default')$('#panel').innerHTML=teamHome();else{const q=$('#claim-quote');if(q)q.insertAdjacentHTML('afterend',`<div class="evidence-status checker">▱ 3 sources connected · ${claim==='cycling'?'figures differ':'different milestones'}</div>`);}annotate()};
function openMobile(){if(matchMedia('(max-width:680px)').matches)$('#context').classList.add('mobile-open')}
function showLektor(){state='default';sync();panelView='lektor';$('#panel').innerHTML=`<button class="back" data-writing>← Back to writing</button><div class="label lektor">⋯ Lektor · opening paragraph</div><p class="resource-intro">Descriptive observations. You choose whether and how to revise.</p>${lektorCards(team.lektor.mode==='Proactive')}`;openMobile()}
$('#panel').addEventListener('click',e=>{if(e.target.closest('[data-review-lektor]'))showLektor();if(e.target.closest('[data-settings]'))settingsPanel();if(e.target.closest('[data-writing]')){render();selectNav('Writing')}});
$('#panel').addEventListener('change',e=>{const t=e.target;if(t.dataset.visible){team[t.dataset.visible].visible=t.checked;}else if(t.dataset.enabled){team[t.dataset.enabled].enabled=t.checked;if(!t.checked)team[t.dataset.enabled].visible=false;}else if(t.dataset.mode){team[t.dataset.mode].mode=t.value;}else if(t.dataset.focus){focuses[t.dataset.focus]=t.checked;}else return;annotate();if(panelView==='settings')settingsPanel();else render();});
document.querySelector('[data-view="AI Team"]').onclick=settingsPanel;
$('#article').addEventListener('click',e=>{if(e.target.closest('.lektor-anchor')&&team.lektor.visible&&team.lektor.enabled&&Object.values(focuses).some(Boolean))showLektor()});
document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{const p=$('#article').querySelectorAll('p')[Number(b.dataset.section)];if(p){p.scrollIntoView({behavior:'smooth',block:'center'});const r=document.createRange();r.selectNodeContents(p);r.collapse(true);getSelection().removeAllRanges();getSelection().addRange(r);$('#article').focus({preventScroll:true});}document.querySelectorAll('.sections button').forEach(n=>n.classList.toggle('current',n===b));});
// Version snapshots contain only user-authored content; display-only role classes are excluded.
function snapshot(){const copy=$('#article').cloneNode(true);copy.querySelectorAll('[data-human-preview]').forEach(n=>n.remove());copy.querySelectorAll('*').forEach(n=>{n.classList.remove('selected','lektor-anchor','human-selected');n.removeAttribute('data-section');n.removeAttribute('title');});return{title:$('#title').innerText,body:copy.innerHTML}}
let versions=[];try{const v=JSON.parse(read('authoria-versions')||'[]');if(Array.isArray(v))versions=v.filter(x=>x&&typeof x.name==='string'&&x.draft&&typeof x.draft.body==='string');}catch{}
let lastSnapshot=JSON.stringify(snapshot()),saveTimer;
function saveSnapshot(manualName){const d=snapshot(),raw=JSON.stringify(d);const persisted=save('authoria-draft',raw);if(manualName||raw!==lastSnapshot||!versions.length){const entry={id:Date.now().toString(36)+Math.random().toString(36).slice(2,6),name:manualName||'Automatic save',kind:manualName?'milestone':'automatic',at:new Date().toISOString(),draft:d};versions.unshift(entry);if(!save('authoria-versions',JSON.stringify(versions))){versions.shift();$('#save-status').textContent='History storage unavailable';return false;}}lastSnapshot=raw;$('#save-status').textContent=persisted?'Autosaved in this browser':'Session only · storage unavailable';return persisted}
for(const el of [$('#title'),$('#article')])el.addEventListener('input',()=>{count();$('#save-status').textContent='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveSnapshot(),900);if($('#claim-quote'))$('#claim-quote').textContent=document.querySelector(`[data-claim="${activeClaim}"]`)?.textContent||'The linked claim has been removed.';});
window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);saveSnapshot()});
const dialog=$('#versions-dialog');$('#close-dialog').onclick=()=>dialog.close();
function openDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!dialog.open)dialog.showModal()}
function historyPanel(){clearTimeout(saveTimer);saveSnapshot();openDialog('Version history',`<p class="resource-intro">Automatic saves and named milestones, stored in this browser. Select a version to read it.</p><div class="version-list">${versions.map(v=>`<button data-version="${v.id}"><strong>${esc(v.name)}</strong><small>${v.kind==='milestone'?'Manual milestone':'Automatic save'} · ${esc(new Date(v.at).toLocaleString())}</small></button>`).join('')}</div>`)}
$('#history-button').onclick=historyPanel;
$('#milestone-button').onclick=()=>openDialog('Save a version','<form id="milestone-form"><label for="version-name">Milestone name</label><input id="version-name" required maxlength="100" placeholder="First complete draft" autofocus><p class="quiet-note">Create a named snapshot of your current article.</p><button class="primary" type="submit">Save milestone</button></form>');
$('#dialog-body').addEventListener('submit',e=>{e.preventDefault();const name=$('#version-name').value.trim();if(!name)return;clearTimeout(saveTimer);if(saveSnapshot(name))historyPanel()});
$('#dialog-body').addEventListener('click',e=>{if(e.target.closest('[data-history-back]'))return historyPanel();const b=e.target.closest('[data-version]');if(!b)return;const v=versions.find(x=>x.id===b.dataset.version);if(!v)return;const doc=new DOMParser().parseFromString(v.draft.body,'text/html');openDialog(v.name,`<button class="back" data-history-back>← Version history</button><p class="quiet-note">Read-only snapshot · ${esc(new Date(v.at).toLocaleString())}</p><h3>${esc(v.draft.title)}</h3><div class="snapshot-text">${esc(doc.body.textContent)}</div>`)});
// Escape dismisses dialogs without resetting the writing context.
dialog.addEventListener('keydown',e=>{if(e.key==='Escape')e.stopPropagation()});
const gapText='gaps remain at several busy junctions';
const gapParagraph=[...$('#article').querySelectorAll('p')].find(p=>p.textContent.includes(gapText));
if(gapParagraph&&!gapParagraph.querySelector('[data-evidence]'))gapParagraph.innerHTML=gapParagraph.innerHTML.replace(gapText,'<span data-evidence="unconnected" tabindex="0" role="button" aria-label="Explore evidence for remaining network gaps">'+gapText+'</span>');
function noSource(){state='default';sync();document.querySelector('[data-evidence]')?.classList.add('selected');$('#panel').innerHTML='<button class="back" data-writing>← Back to writing</button><div class="label">Selected claim</div><blockquote class="quote">Gaps remain at several busy junctions.</blockquote><div class="evidence-status checker">▱ No source connected</div><p class="resource-intro">No source is attached to this passage in the mock draft. This describes the evidence available here, not whether the claim is true.</p>'+why('This passage has no source link in the prototype. You explicitly opened its evidence status.');openMobile();}
$('#article').addEventListener('click',e=>{if(e.target.closest('[data-evidence]'))noSource()});
$('#article').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.closest('[data-evidence]')){e.preventDefault();noSource()}});
annotate();saveSnapshot();render();
